-- Probabilidad de falla de cada enlace ante el sismo official20100227063411530_30 (M8.8, prof. 22.9 km)
-- PGA: Youngs et al. (1997), interplaca, suelo, Rrup al plano de ruptura del ShakeMap USGS
-- P(falla) = P(PGA > 0.215 g), sigma = 0.65
DROP TABLE IF EXISTS probabilidad_falla;
CREATE TABLE probabilidad_falla (
  id_enlace int PRIMARY KEY,
  tipo text,
  km float,
  rrup_km float,
  pga_g float,
  prob_falla float
);
